/bin/bash -lc "cat > harness/profile.sh <<'BASH'
#"'!/usr/bin/env bash
set -euo pipefail
mkdir -p out/profile
export HARNESS_BASELINE=${BASELINE_DIR:-$PWD/baseline-published}
export HARNESS_PRELOAD=$(realpath "$(dirname "$0")/activity.so")
python3 - <<'"'PY'
import collections, json, math, os, pathlib, re, subprocess, threading, time
out=pathlib.Path('out/profile').resolve()
activity=out/'cuda_activity.tsv'
samples=[]
stop=threading.Event()
start=time.monotonic()
def sample():
    with open(out/'nvidia-smi.csv','w') as raw:
        while not stop.is_set():
            p=subprocess.run(['nvidia-smi','--id=0','--query-gpu=utilization.gpu','--format=csv,noheader,nounits'],capture_output=True,text=True,timeout=10)
            t=time.monotonic()-start
            raw.write(f'{t:.9f},{p.stdout.strip()},{p.stderr.strip()}\\n'); raw.flush()
            if p.returncode==0:
                try:
                    util=float(p.stdout.strip())
                    if math.isfinite(util) and 0<=util<=100: samples.append({'t':t,'util':util})
                except ValueError: pass
            stop.wait(.2)
env=os.environ.copy()
env.update(CUDA_VISIBLE_DEVICES='0',HARNESS_ACTIVITY=str(activity),LD_PRELOAD=os.environ['HARNESS_PRELOAD'])
thread=threading.Thread(target=sample); thread.start()
try:
    with open(out/'baseline.log','w') as log:
        begin=time.monotonic()
        p=subprocess.run([os.environ['HARNESS_BASELINE']+'/build-mc/MonteCarloMultiGPU','--method=streamed','--scaling=strong'],stdout=log,stderr=subprocess.STDOUT,env=env,timeout=1100)
        elapsed=time.monotonic()-begin
finally:
    stop.set(); thread.join()
json.dump(samples,open(out/'gpu_util.json','w'),allow_nan=False)
if not samples: raise SystemExit('No valid GPU utilisation samples')
(out/'exit_status').write_text(str(p.returncode)+'\\n')
if p.returncode"'!=0: raise SystemExit('"'Profile baseline failed; see baseline.log')
s=(out/'baseline.log').read_text()
for pattern,expected in [(r'GPU count\\s*:\\s*(\\d+)',1),(r'Option(?:s)? count\\s*:\\s*(\\d+)',1048576),(r'Path(?:s)?(?: count| per option)?\\s*:\\s*(\\d+)',262144)]:
    m=re.search(pattern,s,re.I)
    if not m or int(m[1])"'!=expected: raise SystemExit('"'Missing/invalid representative configuration: '+pattern)
if not re.search(r'Test (passed|failed"'!)'"',s): raise SystemExit('Missing baseline verdict')
events=[]; origin=end=None
for line in activity.read_text().splitlines():
    a=line.split('\\t')
    if a[0]=='begin': origin=int(a[1])
    elif a[0]=='end': end=int(a[1])
    elif a[0]=='event':
        kind,x,y,name=a[1],int(a[2]),int(a[3]),a[4]
        if x<=0 or y<x: raise SystemExit('Invalid CUPTI event timestamps')
        events.append((x,y,kind,name))
if origin is None or end is None or end<=origin or not events: raise SystemExit('Missing CUDA activity records')
# Sweep the union of device activities: overlapping transfers/kernels contribute
# once to critical-path wall time. GPU time is available only for actual device
# activity. Host intervals have no claimed GPU time.
edges={origin,end}
for x,y,_,_ in events:
    if x<origin or y>end: raise SystemExit('CUPTI timestamps outside measured run')
    edges.update((x,y))
edges=sorted(edges)
first=min(e[0] for e in events); last=max(e[1] for e in events)
stages=[]
for x,y in zip(edges,edges[1:]):
    if y<=x: continue
    active=[e for e in events if e[0]<=x and e[1]>=y]
    if active:
        # Prefer compute when concurrent device operations occupy the same span.
        event=min(active,key=lambda e:(e[2]"'!='"'compute',e[2]"'!='"'transfer',e[3]))
        kind,name=event[2:]; gpu=(y-x)/1e9
        name='CUDA '+name
    else:
        kind='other'; gpu=None
        name=('host initialization and allocation' if y<=first else
              'host finalization and validation' if x>=last else
              'host work and device idle between activities')
    duration=(y-x)/1e9
    if stages and stages[-1]['stage']==name and stages[-1]['kind']==kind:
        stages[-1]['wall_s']+=duration
        if gpu is not None: stages[-1]['gpu_s']+=gpu
    else: stages.append(dict(stage=name,kind=kind,wall_s=duration,gpu_s=gpu))
# The total includes launch, transfers, synchronization, validation and teardown.
if not math.isfinite(elapsed) or elapsed<=0: raise SystemExit('Invalid total wall time')
if len(stages)<3: raise SystemExit('Fewer than three observed internal stages')
if any(abs(x['wall_s']-elapsed)<=.02*elapsed for x in stages):
    raise SystemExit('One stage spans >=98% of process time; insufficient stage resolution')
if sum(x['wall_s'] for x in stages)/elapsed < .9:
    raise SystemExit('CUDA activity timeline covers less than 90% of run')
json.dump(stages,open(out/'stages.json','w'),allow_nan=False,indent=2)
json.dump({'total_wall_s':elapsed},open(out/'total_wall_s.json','w'),allow_nan=False)
